    ON c.DonorID = d.ID AND c.ScheduledDate = DATEADD(MINUTE, v.CollectionMinute, DATEADD(DAY, v.CollectionDayOffset, CAST(CAST(SYSDATETIME() AS DATE) AS DATETIME2(0))))
LEFT JOIN dbo.PhoneCall pc
    ON pc.DonorID = d.ID AND pc.ScheduledDate = DATEADD(MINUTE, v.CallMinute, DATEADD(DAY, v.CallDayOffset, CAST(CAST(SYSDATETIME() AS DATE) AS DATETIME2(0))))
LEFT JOIN dbo.RecurringDonation rd ON rd.DonorID = d.ID;

INSERT INTO dbo.Donation
    (DonorID, DonationDate, TotalAmount, PaymentMethod, TargetCampaign, Notes,
     CollectionID, CallID, RecurringDonationID)
